import re

def normalizar_pedido(texto: str) -> dict:
    padrao = r"PED-(\d+) \s*\| \s*item\s+([a-zA-Z0-9]+)\s*(?:\|\s*qtd\s+(\d+))?\s*$"
    match = re.match(padrao, texto)

    if not match:
        raise ValueError("Linha não contém 'PED-<numero>' e 'item <sku>'")

    pedido = match.group(1)
    item = match.group(2).upper()
    quantidade = int(match.group(3)) if match.group(3) else 1

    return {"pedido": pedido, "item": item, "quantidade": quantidade}

